import { lazy, Suspense, StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { RouterProvider, createRouter } from "@tanstack/react-router";
import { QueryClientProvider } from "@tanstack/react-query";

// Auto-generated by the TanStack Router Vite plugin — DO NOT EDIT MANUALLY
import { routeTree } from "./routeTree.gen";

import { queryClient } from "@/lib/query-client";
import "./index.css";

/**
 * Create the router instance.
 * Pass `context` here for things every route can read (e.g. queryClient).
 */
const router = createRouter({
  routeTree,
  context: { queryClient },
  // Scroll to top on navigation
  scrollRestoration: true,
});

// TypeScript — register the router for full type inference
declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}

const DesktopSchoolGate =
  import.meta.env.VITE_TARGET === "desktop"
    ? lazy(() => import("./lib/platform/desktop/school-gate"))
    : null;

const rootEl = document.getElementById("root");
if (!rootEl) throw new Error("No #root element found in index.html");

const application = (
  <QueryClientProvider client={queryClient}>
    <RouterProvider router={router} />
  </QueryClientProvider>
);

createRoot(rootEl).render(
  <StrictMode>
    <Suspense fallback={<div role="status">Loading SchoolHub…</div>}>
      {DesktopSchoolGate ? (
        <DesktopSchoolGate>{application}</DesktopSchoolGate>
      ) : (
        application
      )}
    </Suspense>
  </StrictMode>,
);
